        "api": 1,
        "source": "// Mines the cobblestone in front of the bot with the pickaxes in slots 1 to 9,\n// one after the other, and stops when the last one is nearly used up.\nfn on_join(first) {\n    if first {\n        state.slot = 1;\n    }\n    hotbar.select(state.slot);\n    look.at(0.0, 20.0);\n    timer.every(1000, \"mine\");\n}\n\nfn on_timer(name) {\n    if mouse.left.held {\n        return; // still mining\n    }\n    let result = mouse.left.hold();\n    if result.ok {\n        return;\n    }\n    if result.reason == \"tool_guard\" || bot.held == () {\n        next_pickaxe();\n    }\n}\n\nfn next_pickaxe() {\n    if state.slot == 9 {\n        log.info(\"No pickaxe left.\");\n        timer.cancel(\"mine\");\n        return;\n    }\n    state.slot += 1;\n    hotbar.select(state.slot);\n}\n",
